// --- Domain Lock (Bloqueo por Dominio) ---
const dominioPermitido = 'estev1000.github.io';

(function bloquearPorDominio() {
    const host = window.location.hostname;
    const permitidos = [dominioPermitido, 'localhost', '127.0.0.1', ''];

    if (permitidos.indexOf(host) === -1) {
        document.body.innerHTML = '<div style="font-family: Arial, sans-serif; text-align: center; margin-top: 40vh;"><h1>Acceso no autorizado</h1><p>Esta aplicación solo puede ejecutarse en el dominio autorizado.</p></div>';
        throw new Error('Domain Lock: dominio no permitido');
    }
})();

// ============================================================
// Almacenamiento — Empresa única
// ============================================================

function lsGet(clave, defecto) {
    try {
        const valor = localStorage.getItem(clave);
        return valor === null ? defecto : JSON.parse(valor);
    } catch (e) {
        return defecto;
    }
}

function lsSet(clave, valor) {
    localStorage.setItem(clave, JSON.stringify(valor));
}

// Ids únicos aunque dos registros se creen en el mismo milisegundo
let ultimoId = Date.now();
function nuevoId() {
    ultimoId = Math.max(Date.now(), ultimoId + 1);
    return ultimoId;
}

function kDatos(idEmpresa, coleccion) {
    return 'prosueldos:empresa:' + idEmpresa + ':' + coleccion;
}

// ============================================================
// EMPRESA ÚNICA DEL SISTEMA
// ============================================================

const EMPRESA = {
    nombre: 'Percepción, medios y comunicación S.A.',
    cuit: '30-71008900-7',
    domicilio: 'De Maria 4617 1°A - CABA',
    actividad: 'Servicios de publicidad',
    lugarPago: 'Ciudad Autónoma de Buenos Aires',
    modalidadPago: 'Transferencia bancaria'
};

// Detectar el id existente de Percepción (compatibilidad con datos previos)
const empresasPrevias = lsGet('prosueldos:empresas', []);
const previa = empresasPrevias.find(e => (e.cuit && e.cuit === EMPRESA.cuit) || e.nombre === EMPRESA.nombre);
const EMPRESA_ID = previa ? previa.id : 1;

// Estado
let empleados = [];
let novedades = [];
let catalogoConceptos = [];
let aplicacionesConceptos = [];
let convenios = [];
let configRecibo = null;

function cargarDatos() {
    empleados = lsGet(kDatos(EMPRESA_ID, 'empleados'), []);
    novedades = lsGet(kDatos(EMPRESA_ID, 'novedades'), []);
    catalogoConceptos = lsGet(kDatos(EMPRESA_ID, 'conceptos'), []);
    aplicacionesConceptos = lsGet(kDatos(EMPRESA_ID, 'aplicaciones'), []);
    convenios = lsGet(kDatos(EMPRESA_ID, 'convenios'), []);
    cargarConfigRecibo();
}

function saveData() {
    lsSet(kDatos(EMPRESA_ID, 'empleados'), empleados);
    lsSet(kDatos(EMPRESA_ID, 'novedades'), novedades);
    lsSet(kDatos(EMPRESA_ID, 'conceptos'), catalogoConceptos);
    lsSet(kDatos(EMPRESA_ID, 'aplicaciones'), aplicacionesConceptos);
    lsSet(kDatos(EMPRESA_ID, 'convenios'), convenios);
    lsSet(kDatos(EMPRESA_ID, 'configRecibo'), configRecibo);
}

// Escapado básico para datos de usuario
function esc(texto) {
    if(texto === null || texto === undefined) return '';
    return String(texto)
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&#39;');
}

function money(valor) {
    return '$' + Number(valor || 0).toLocaleString('es-AR');
}

// Tab Switching function
function switchTab(tabId, navEl) {
    document.querySelectorAll('.page-content').forEach(el => el.classList.remove('active'));
    document.querySelectorAll('.nav-item').forEach(el => el.classList.remove('active'));

    document.getElementById(tabId + '-page').classList.add('active');
    const nav = navEl && navEl.classList
        ? navEl
        : document.querySelector('.nav-item[data-tab="' + tabId + '"]');
    if (nav) nav.classList.add('active');

    const titles = {
        'empleados': 'Gestión de Empleados',
        'novedades': 'Adelantos y Faltas',
        'conceptos': 'Conceptos Configurables',
        'recibo': 'Generador de Recibos',
        'convenios': 'Convenios Colectivos (CCT)',
        'configrecibo': 'Aportes y Contribuciones (Dec 407/2026)'
    };
    document.getElementById('page-title').innerText = titles[tabId] || '';

    if(tabId === 'convenios') { renderConvenios(); renderCategorias(); }
    if(tabId === 'empleados') renderEmpleados();
    if(tabId === 'novedades') updateSelects('nov-select-emp');
    if(tabId === 'conceptos') renderConceptosCatalogo();
    if(tabId === 'configrecibo') renderConfigRecibo();
    if(tabId === 'recibo') {
        updateSelects('recibo-emp');
        updateConceptoSelect();
        renderAplicacionesConceptos();
    }

    renderNovedades(); // Reload data if needed
}

// Set Date
const dateOptions = { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' };
document.getElementById('date-display').innerText = new Date().toLocaleDateString('es-AR', dateOptions);

// ============================================================
// ÍTEM 2 — CONVENIOS (CCT) Y CATEGORÍAS
// ============================================================

function convSeleccionadoId() {
    const sel = document.getElementById('conv-categoria-de');
    return sel ? parseInt(sel.value) : null;
}

function actualizarSelectsConvenio() {
    const selCat = document.getElementById('conv-categoria-de');
    const selEmp = document.getElementById('emp-convenio');
    const actualCat = selCat ? selCat.value : '';
    const actualEmp = selEmp ? selEmp.value : '';

    if (selCat) {
        selCat.innerHTML = convenios.length === 0
            ? '<option value="">Sin convenios cargados</option>'
            : '<option value="">Selecciona un convenio...</option>';
        convenios.forEach(c => {
            selCat.innerHTML += `<option value="${c.id}">${esc(c.nombre)}</option>`;
        });
        if (actualCat && convenios.some(c => String(c.id) === actualCat)) selCat.value = actualCat;
    }

    if (selEmp) {
        selEmp.innerHTML = convenios.length === 0
            ? '<option value="">Sin convenios cargados</option>'
            : '<option value="">Sin convenio / cargar después</option>';
        convenios.forEach(c => {
            selEmp.innerHTML += `<option value="${c.id}">${esc(c.nombre)}</option>`;
        });
        if (actualEmp && convenios.some(c => String(c.id) === actualEmp)) selEmp.value = actualEmp;
    }
}

function guardarConvenio() {
    const editId = document.getElementById('conv-edit-id').value;
    const nombre = document.getElementById('conv-nombre').value.trim();
    const vigencia = document.getElementById('conv-vigencia').value.trim();

    if (!nombre) return alert("Ingresá el nombre del convenio colectivo");

    if (editId) {
        const convenio = convenios.find(c => c.id === parseInt(editId));
        if (convenio) {
            convenio.nombre = nombre;
            convenio.vigencia = vigencia;
        }
        cancelarEdicionConvenio();
    } else {
        const duplicado = convenios.some(c => c.nombre.toLowerCase() === nombre.toLowerCase());
        if (duplicado) return alert("Ya existe un convenio con ese nombre");
        convenios.push({ id: nuevoId(), nombre, vigencia, categorias: [] });
        document.getElementById('conv-nombre').value = '';
        document.getElementById('conv-vigencia').value = '';
    }

    saveData();
    actualizarSelectsConvenio();
    renderConvenios();
    renderCategorias();
}

function editarConvenio(id) {
    const convenio = convenios.find(c => c.id === id);
    if (!convenio) return;
    document.getElementById('conv-edit-id').value = convenio.id;
    document.getElementById('conv-nombre').value = convenio.nombre;
    document.getElementById('conv-vigencia').value = convenio.vigencia || '';
    document.getElementById('btn-guardar-convenio').innerText = 'Actualizar Convenio';
    document.getElementById('btn-cancelar-convenio').style.display = 'inline-block';
    window.scrollTo(0, 0);
}

function cancelarEdicionConvenio() {
    const edit = document.getElementById('conv-edit-id');
    if (!edit) return;
    edit.value = '';
    document.getElementById('conv-nombre').value = '';
    document.getElementById('conv-vigencia').value = '';
    document.getElementById('btn-guardar-convenio').innerText = 'Guardar Convenio';
    document.getElementById('btn-cancelar-convenio').style.display = 'none';
}

function borrarConvenio(id) {
    const convenio = convenios.find(c => c.id === id);
    if (!convenio) return;
    const enUso = empleados.filter(e => e.convenioId === id).length;
    const aviso = enUso > 0
        ? "Este convenio lo usan " + enUso + " empleado(s). Se le quitará de sus fichas (el sueldo cargado se mantiene)."
        : "¿Eliminar el convenio \"" + convenio.nombre + "\" y todas sus categorías?";
    if (!confirm(aviso)) return;

    convenios = convenios.filter(c => c.id !== id);
    empleados.forEach(e => {
        if (e.convenioId === id) {
            e.convenioId = null;
            e.convenioNombre = '';
            e.categoriaId = null;
            e.categoriaNombre = '';
        }
    });

    saveData();
    actualizarSelectsConvenio();
    renderConvenios();
    renderCategorias();
    renderEmpleados();
}

function renderConvenios() {
    const tbody = document.getElementById('lista-convenios');
    if (!tbody) return;
    tbody.innerHTML = '';

    if (convenios.length === 0) {
        tbody.innerHTML = '<tr><td colspan="4" style="color: var(--text-muted);">Sin convenios cargados. Cargá el CCT que aplique (ej: Comercio, Industria, Construcción, Personal de Directiva).</td></tr>';
        return;
    }

    convenios.forEach(c => {
        tbody.innerHTML += `
            <tr>
                <td style="font-weight: 500;">${esc(c.nombre)}</td>
                <td>${esc(c.vigencia || '—')}</td>
                <td>${(c.categorias || []).length}</td>
                <td>
                    <button class="action-btn" onclick="editarConvenio(${c.id})">Editar</button>
                    <button class="action-btn" onclick="selConvenioCategorias(${c.id})">Ver categorías</button>
                    <button class="action-btn delete" onclick="borrarConvenio(${c.id})">Eliminar</button>
                </td>
            </tr>
        `;
    });
}

function selConvenioCategorias(valor) {
    const sel = document.getElementById('conv-categoria-de');
    if (!sel) return;
    if (valor !== undefined && valor !== null) sel.value = String(valor);
    cancelarEdicionCategoria();
    renderCategorias();
}

function convenioSeleccionado() {
    const id = convSeleccionadoId();
    if (!id) return null;
    return convenios.find(c => c.id === id) || null;
}

function guardarCategoria() {
    const convenio = convenioSeleccionado();
    if (!convenio) return alert("Seleccioná un convenio para cargar sus categorías");

    const editId = document.getElementById('catconv-edit-id').value;
    const nombre = document.getElementById('catconv-nombre').value.trim();
    const basico = parseFloat(document.getElementById('catconv-basico').value);

    if (!nombre) return alert("Ingresá el nombre de la categoría o escala");
    if (!basico || basico <= 0) return alert("Ingresá el sueldo básico de la categoría");

    const cats = convenio.categorias || (convenio.categorias = []);

    if (editId) {
        const categoria = cats.find(c => c.id === parseInt(editId));
        if (categoria) {
            categoria.nombre = nombre;
            categoria.basico = basico;
        }
        cancelarEdicionCategoria();
    } else {
        const duplicado = cats.some(c => c.nombre.toLowerCase() === nombre.toLowerCase());
        if (duplicado) return alert("Ya existe esa categoría en este convenio");
        cats.push({ id: nuevoId(), nombre, basico });
        document.getElementById('catconv-nombre').value = '';
        document.getElementById('catconv-basico').value = '';
    }

    saveData();
    renderConvenios();
    renderCategorias();
    updateCategoriasEmpleado();
}

function editarCategoria(convId, catId) {
    const convenio = convenios.find(c => c.id === convId);
    if (!convenio) return;
    const categoria = (convenio.categorias || []).find(c => c.id === catId);
    if (!categoria) return;

    const sel = document.getElementById('conv-categoria-de');
    if (sel) sel.value = String(convId);

    document.getElementById('catconv-edit-id').value = categoria.id;
    document.getElementById('catconv-nombre').value = categoria.nombre;
    document.getElementById('catconv-basico').value = categoria.basico;
    document.getElementById('btn-guardar-catconv').innerText = 'Actualizar Categoría';
    document.getElementById('btn-cancelar-catconv').style.display = 'inline-block';
    window.scrollTo(0, document.body.scrollHeight);
}

function cancelarEdicionCategoria() {
    const edit = document.getElementById('catconv-edit-id');
    if (!edit) return;
    edit.value = '';
    document.getElementById('catconv-nombre').value = '';
    document.getElementById('catconv-basico').value = '';
    document.getElementById('btn-guardar-catconv').innerText = 'Agregar Categoría';
    document.getElementById('btn-cancelar-catconv').style.display = 'none';
}

function borrarCategoria(convId, catId) {
    const convenio = convenios.find(c => c.id === convId);
    if (!convenio) return;
    const categoria = (convenio.categorias || []).find(c => c.id === catId);
    if (!categoria) return;

    const enUso = empleados.filter(e => e.categoriaId === catId).length;
    const aviso = enUso > 0
        ? "Esta categoría la usan " + enUso + " empleado(s). Se le quitará de sus fichas (el sueldo cargado se mantiene)."
        : "¿Eliminar la categoría \"" + categoria.nombre + "\"?";
    if (!confirm(aviso)) return;

    convenio.categorias = convenio.categorias.filter(c => c.id !== catId);
    empleados.forEach(e => {
        if (e.categoriaId === catId) {
            e.categoriaId = null;
            e.categoriaNombre = '';
        }
    });

    saveData();
    cancelarEdicionCategoria();
    renderConvenios();
    renderCategorias();
    renderEmpleados();
}

function renderCategorias() {
    const tbody = document.getElementById('lista-categorias');
    if (!tbody) return;
    tbody.innerHTML = '';

    const convenio = convenioSeleccionado();

    if (!convenio) {
        tbody.innerHTML = '<tr><td colspan="3" style="color: var(--text-muted);">Elegí un convenio arriba para ver y cargar sus categorías.</td></tr>';
        return;
    }

    const cats = convenio.categorias || [];
    if (cats.length === 0) {
        tbody.innerHTML = '<tr><td colspan="3" style="color: var(--text-muted);">El convenio "' + esc(convenio.nombre) + '" todavía no tiene categorías cargadas.</td></tr>';
        return;
    }

    cats.forEach(c => {
        tbody.innerHTML += `
            <tr>
                <td style="font-weight: 500;">${esc(c.nombre)}</td>
                <td>${money(c.basico)}</td>
                <td>
                    <button class="action-btn" onclick="editarCategoria(${convenio.id}, ${c.id})">Editar</button>
                    <button class="action-btn delete" onclick="borrarCategoria(${convenio.id}, ${c.id})">Eliminar</button>
                </td>
            </tr>
        `;
    });
}

// --- Empleados: convenio y categoría ---
function updateCategoriasEmpleado(preseleccion) {
    const select = document.getElementById('emp-categoria');
    if (!select) return;

    const convenioId = parseInt(document.getElementById('emp-convenio').value);
    const convenio = convenios.find(c => c.id === convenioId);

    select.innerHTML = convenio
        ? '<option value="">Selecciona una categoría...</option>'
        : '<option value="">Sin convenio seleccionado</option>';

    if (convenio) {
        (convenio.categorias || []).forEach(c => {
            select.innerHTML += `<option value="${c.id}" data-basico="${c.basico}">${esc(c.nombre)} — ${money(c.basico)}</option>`;
        });
    }

    if (preseleccion) select.value = String(preseleccion);
}

function cambioConvenioEmpleado() {
    updateCategoriasEmpleado();
    const empId = document.getElementById('emp-edit-id').value;
    if (!empId) document.getElementById('emp-sueldo').value = '';
}

function cambioCategoriaEmpleado() {
    const select = document.getElementById('emp-categoria');
    const opcion = select.options[select.selectedIndex];
    const basico = opcion ? opcion.getAttribute('data-basico') : null;
    if (basico !== null && basico !== '') document.getElementById('emp-sueldo').value = basico;
}

// ============================================================
// Empleados
// ============================================================

function guardarEmpleado() {
    const editId = document.getElementById('emp-edit-id').value;
    const nombre = document.getElementById('emp-nombre').value;
    const cuil = document.getElementById('emp-cuil').value;
    const puesto = document.getElementById('emp-puesto').value;
    const sueldo = parseFloat(document.getElementById('emp-sueldo').value);

    const convId = parseInt(document.getElementById('emp-convenio').value) || null;
    const catId = parseInt(document.getElementById('emp-categoria').value) || null;
    const convenio = convId ? convenios.find(c => c.id === convId) : null;
    const categoria = convenio && catId ? (convenio.categorias || []).find(c => c.id === catId) : null;

    if(!nombre || !sueldo) return alert("Nombre y Sueldo Básico son obligatorios");

    const ficha = {
        nombre, cuil, puesto, sueldo,
        convenioId: convenio ? convenio.id : null,
        convenioNombre: convenio ? convenio.nombre : '',
        categoriaId: categoria ? categoria.id : null,
        categoriaNombre: categoria ? categoria.nombre : ''
    };

    if (editId) {
        const empleado = empleados.find(e => e.id === parseInt(editId));
        if (empleado) Object.assign(empleado, ficha);
        cancelarEdicionEmpleado();
    } else {
        empleados.push(Object.assign({ id: nuevoId() }, ficha));
        limpiarFormEmpleado();
    }

    saveData();
    renderEmpleados();
}

function limpiarFormEmpleado() {
    document.getElementById('emp-nombre').value = '';
    document.getElementById('emp-cuil').value = '';
    document.getElementById('emp-puesto').value = '';
    document.getElementById('emp-sueldo').value = '';
    document.getElementById('emp-convenio').value = '';
    updateCategoriasEmpleado();
    document.getElementById('emp-edit-id').value = '';
    document.getElementById('btn-guardar-empleado').innerText = 'Guardar Empleado';
    document.getElementById('btn-cancelar-empleado').style.display = 'none';
}

function editarEmpleado(id) {
    const empleado = empleados.find(e => e.id === id);
    if (!empleado) return;

    document.getElementById('emp-edit-id').value = empleado.id;
    document.getElementById('emp-nombre').value = empleado.nombre;
    document.getElementById('emp-cuil').value = empleado.cuil || '';
    document.getElementById('emp-puesto').value = empleado.puesto || '';
    document.getElementById('emp-sueldo').value = empleado.sueldo;
    document.getElementById('emp-convenio').value = empleado.convenioId ? String(empleado.convenioId) : '';
    updateCategoriasEmpleado(empleado.categoriaId);

    document.getElementById('btn-guardar-empleado').innerText = 'Actualizar Empleado';
    document.getElementById('btn-cancelar-empleado').style.display = 'inline-block';
    window.scrollTo(0, 0);
}

function cancelarEdicionEmpleado() {
    const edit = document.getElementById('emp-edit-id');
    if (!edit) return;
    limpiarFormEmpleado();
}

function borrarEmpleado(id) {
    if(confirm("¿Seguro que deseas eliminar a este empleado?")) {
        empleados = empleados.filter(e => e.id !== id);
        novedades = novedades.filter(n => n.empId !== id);
        aplicacionesConceptos = aplicacionesConceptos.filter(a => a.empId !== id);
        saveData();
        renderEmpleados();
        renderNovedades();
        renderAplicacionesConceptos();
    }
}

function renderEmpleados() {
    const tbody = document.getElementById('lista-empleados');
    if (!tbody) return;
    tbody.innerHTML = '';

    if (empleados.length === 0) {
        tbody.innerHTML = '<tr><td colspan="6" style="color: var(--text-muted);">Sin empleados cargados.</td></tr>';
        return;
    }

    empleados.forEach(e => {
        const conv = e.convenioNombre
            ? `<div style="font-weight:500;">${esc(e.convenioNombre)}</div><div style="color: var(--text-muted); font-size: 0.85rem;">${esc(e.categoriaNombre || 'Sin categoría')}</div>`
            : '<span style="color: var(--text-muted);">Sin convenio</span>';

        tbody.innerHTML += `
            <tr>
                <td style="font-weight: 500;">${esc(e.nombre)}</td>
                <td>${esc(e.cuil)}</td>
                <td>${esc(e.puesto || '—')}</td>
                <td>${conv}</td>
                <td>${money(e.sueldo)}</td>
                <td>
                    <button class="action-btn" onclick="editarEmpleado(${e.id})">Editar</button>
                    <button class="action-btn delete" onclick="borrarEmpleado(${e.id})">Eliminar</button>
                </td>
            </tr>
        `;
    });
}

// --- Novedades (Adelantos) ---
function updateSelects(selectId) {
    const select = document.getElementById(selectId);
    if (!select) return;
    select.innerHTML = '<option value="">Selecciona un empleado...</option>';
    empleados.forEach(e => {
        select.innerHTML += `<option value="${e.id}">${e.nombre}</option>`;
    });
}

function guardarNovedad() {
    const empId = document.getElementById('nov-select-emp').value;
    const tipo = document.getElementById('nov-tipo').value;
    const monto = parseFloat(document.getElementById('nov-monto').value);
    const nota = document.getElementById('nov-nota').value;

    if(!empId || !monto) return alert("Selecciona un empleado y un monto");

    const mov = {
        id: nuevoId(),
        empId: parseInt(empId),
        tipo,
        monto,
        nota,
        fecha: new Date().toLocaleDateString('es-AR')
    };

    novedades.push(mov);
    saveData();

    document.getElementById('nov-monto').value = '';
    document.getElementById('nov-nota').value = '';

    renderNovedades();
}

function borrarNovedad(id) {
    novedades = novedades.filter(n => n.id !== id);
    saveData();
    renderNovedades();
}

function renderNovedades() {
    const tbody = document.getElementById('lista-novedades');
    if (!tbody) return;
    tbody.innerHTML = '';
    // Only show latest 100 for performance, reverse chronological
    [...novedades].reverse().forEach(n => {
        const empleado = empleados.find(e => e.id === n.empId);
        const nombre = empleado ? empleado.nombre : 'Eliminado';

        let tipoBadge = '';
        if(n.tipo === 'adelanto') tipoBadge = '<span style="color: var(--warning); border: 1px solid var(--warning); padding: 2px 6px; border-radius: 4px; font-size: 0.8rem;">Adelanto</span>';
        if(n.tipo === 'falta') tipoBadge = '<span style="color: var(--danger); border: 1px solid var(--danger); padding: 2px 6px; border-radius: 4px; font-size: 0.8rem;">Falta</span>';
        if(n.tipo === 'premio') tipoBadge = '<span style="color: var(--success); border: 1px solid var(--success); padding: 2px 6px; border-radius: 4px; font-size: 0.8rem;">Premio</span>';

        tbody.innerHTML += `
            <tr>
                <td>${n.fecha}</td>
                <td style="font-weight: 500;">${nombre}</td>
                <td>${tipoBadge}</td>
                <td>$${n.monto.toLocaleString('es-AR')}</td>
                <td>${esc(n.nota)}</td>
                <td>
                    <button class="action-btn delete" onclick="borrarNovedad(${n.id})">Eliminar</button>
                </td>
            </tr>
        `;
    });
}

// --- Conceptos configurables (Catálogo) ---
function guardarConcepto() {
    const editId = document.getElementById('cat-edit-id').value;
    const nombre = document.getElementById('cat-nombre').value.trim();
    const tipo = document.getElementById('cat-tipo').value;
    const monto = parseFloat(document.getElementById('cat-monto').value) || 0;

    if(!nombre) return alert("Ingresá el nombre del concepto");

    if(editId) {
        const concepto = catalogoConceptos.find(c => c.id === parseInt(editId));
        if(concepto) {
            concepto.nombre = nombre;
            concepto.tipo = tipo;
            concepto.monto = monto;
        }
        cancelarEdicionConcepto();
    } else {
        const duplicado = catalogoConceptos.some(c => c.nombre.toLowerCase() === nombre.toLowerCase() && c.tipo === tipo);
        if(duplicado) return alert("Ya existe un concepto con ese nombre y tipo");
        catalogoConceptos.push({ id: nuevoId(), nombre, tipo, monto });
        document.getElementById('cat-nombre').value = '';
        document.getElementById('cat-monto').value = '';
    }

    saveData();
    renderConceptosCatalogo();
    updateConceptoSelect();
}

function editarConcepto(id) {
    const concepto = catalogoConceptos.find(c => c.id === id);
    if(!concepto) return;
    document.getElementById('cat-edit-id').value = concepto.id;
    document.getElementById('cat-nombre').value = concepto.nombre;
    document.getElementById('cat-tipo').value = concepto.tipo;
    document.getElementById('cat-monto').value = concepto.monto;
    document.getElementById('btn-guardar-concepto').innerText = 'Actualizar Concepto';
    document.getElementById('btn-cancelar-concepto').style.display = 'inline-block';
}

function cancelarEdicionConcepto() {
    document.getElementById('cat-edit-id').value = '';
    document.getElementById('cat-nombre').value = '';
    document.getElementById('cat-tipo').value = 'haber';
    document.getElementById('cat-monto').value = '';
    document.getElementById('btn-guardar-concepto').innerText = 'Guardar Concepto';
    document.getElementById('btn-cancelar-concepto').style.display = 'none';
}

function borrarConcepto(id) {
    if(!confirm("¿Eliminar este concepto del catálogo? (los recibos ya generados no se modifican)")) return;
    catalogoConceptos = catalogoConceptos.filter(c => c.id !== id);
    saveData();
    renderConceptosCatalogo();
    updateConceptoSelect();
}

function renderConceptosCatalogo() {
    const tbody = document.getElementById('lista-catalogo-conceptos');
    if (!tbody) return;
    tbody.innerHTML = '';

    if(catalogoConceptos.length === 0) {
        tbody.innerHTML = '<tr><td colspan="4" style="color: var(--text-muted);">Sin conceptos cargados. Agregá los que uses habitualmente (antigüedad, obra social, aportes, bonos, etc.).</td></tr>';
        return;
    }

    catalogoConceptos.forEach(c => {
        const badge = c.tipo === 'haber'
            ? '<span style="color: var(--success); border: 1px solid var(--success); padding: 2px 6px; border-radius: 4px; font-size: 0.8rem;">Haber (+)</span>'
            : '<span style="color: var(--danger); border: 1px solid var(--danger); padding: 2px 6px; border-radius: 4px; font-size: 0.8rem;">Deducción (-)</span>';

        tbody.innerHTML += `
            <tr>
                <td style="font-weight: 500;">${esc(c.nombre)}</td>
                <td>${badge}</td>
                <td>${money(c.monto)}</td>
                <td>
                    <button class="action-btn" onclick="editarConcepto(${c.id})">Editar</button>
                    <button class="action-btn delete" onclick="borrarConcepto(${c.id})">Eliminar</button>
                </td>
            </tr>
        `;
    });
}

// --- Aplicación de conceptos a un recibo (empleado + período) ---
function updateConceptoSelect() {
    const select = document.getElementById('recibo-concepto');
    if(!select) return;
    select.innerHTML = '<option value="">Selecciona un concepto...</option>';
    catalogoConceptos.forEach(c => {
        const etiqueta = c.tipo === 'haber' ? `${c.nombre} (Haber)` : `${c.nombre} (Deducción)`;
        select.innerHTML += `<option value="${c.id}">${esc(etiqueta)}</option>`;
    });
}

function aplicarConcepto() {
    const empId = document.getElementById('recibo-emp').value;
    const periodo = document.getElementById('recibo-mes').value;
    const conceptoId = parseInt(document.getElementById('recibo-concepto').value);
    const monto = parseFloat(document.getElementById('recibo-concepto-monto').value);

    if(!empId || !periodo) return alert("Seleccioná Empleado y Período en el Generador de Recibos");
    if(!conceptoId) return alert("Seleccioná un concepto del catálogo");
    if(!monto || monto <= 0) return alert("Ingresá un monto válido para el concepto");

    const concepto = catalogoConceptos.find(c => c.id === conceptoId);
    if(!concepto) return;

    aplicacionesConceptos.push({
        id: nuevoId(),
        empId: parseInt(empId),
        conceptoId: concepto.id,
        nombre: concepto.nombre,
        tipo: concepto.tipo,
        monto,
        periodo
    });

    saveData();
    document.getElementById('recibo-concepto').value = '';
    document.getElementById('recibo-concepto-monto').value = '';
    renderAplicacionesConceptos();
    alert("Concepto aplicado. Generá la Vista Previa para verlo en el recibo.");
}

function borrarAplicacionConcepto(id) {
    aplicacionesConceptos = aplicacionesConceptos.filter(a => a.id !== id);
    saveData();
    renderAplicacionesConceptos();
}

function renderAplicacionesConceptos() {
    const tbody = document.getElementById('lista-aplicaciones');
    if(!tbody) return;
    tbody.innerHTML = '';

    if(aplicacionesConceptos.length === 0) {
        tbody.innerHTML = '<tr><td colspan="6" style="color: var(--text-muted);">Sin conceptos aplicados todavía.</td></tr>';
        return;
    }

    [...aplicacionesConceptos].reverse().forEach(a => {
        const empleado = empleados.find(e => e.id === a.empId);
        const nombre = empleado ? empleado.nombre : 'Eliminado';

        let tipoBadge = '';
        if(a.tipo === 'haber') tipoBadge = '<span style="color: var(--success); border: 1px solid var(--success); padding: 2px 6px; border-radius: 4px; font-size: 0.8rem;">Haber (+)</span>';
        if(a.tipo === 'deduccion') tipoBadge = '<span style="color: var(--danger); border: 1px solid var(--danger); padding: 2px 6px; border-radius: 4px; font-size: 0.8rem;">Deducción (-)</span>';

        tbody.innerHTML += `
            <tr>
                <td style="font-weight: 500;">${esc(nombre)}</td>
                <td>${esc(a.periodo)}</td>
                <td>${esc(a.nombre)}</td>
                <td>${tipoBadge}</td>
                <td>${money(a.monto)}</td>
                <td>
                    <button class="action-btn delete" onclick="borrarAplicacionConcepto(${a.id})">Quitar</button>
                </td>
            </tr>
        `;
    });
}

// ============================================================
// ÍTEM 4 — NUEVO FORMATO RECIBO (Dec 407/2026)
// 4 secciones obligatorias, gráfico de composición del costo
// laboral (Anexo III) y motor de aportes y contribuciones por %.
// ============================================================

const CFG_RECIBO_DEFECTO = {
    aportesTrabajador: { jubilacion: 0, obraSocial: 0, pami: 0, sindical: 0, otros: 0 },
    contribucionesEmpleador: { jubilacion: 0, obraSocial: 0, pami: 0, art: 0, sindical: 0, camaras: 0, otros: 0 }
};

const ETIQ_APORTE = { jubilacion: 'Jubilatorio', obraSocial: 'Obra Social', pami: 'PAMI', sindical: 'Sindicato', otros: 'Otros' };
const ETIQ_CONTRIB = { jubilacion: 'Jubilación patronal', obraSocial: 'Obra social patronal', pami: 'PAMI patronal', art: 'ART', sindical: 'Aporte sindical patronal', camaras: 'Cámaras', otros: 'Otros' };

const COLORES_COSTO = {
    remuneracion: '#4F46E5',
    jubilacion: '#0284C7',
    obraSocial: '#10B981',
    pami: '#F59E0B',
    art: '#EF4444',
    sindical: '#8B5CF6',
    camaras: '#64748B',
    otros: '#9CA3AF'
};

function cargarConfigRecibo() {
    const guardado = lsGet(kDatos(EMPRESA_ID, 'configRecibo'), null);
    configRecibo = {
        aportesTrabajador: Object.assign({}, CFG_RECIBO_DEFECTO.aportesTrabajador, (guardado && guardado.aportesTrabajador) || {}),
        contribucionesEmpleador: Object.assign({}, CFG_RECIBO_DEFECTO.contribucionesEmpleador, (guardado && guardado.contribucionesEmpleador) || {})
    };
}

function renderConfigRecibo() {
    if (!configRecibo) cargarConfigRecibo();
    const cfg = configRecibo;
    const valores = {
        'cfg-td-jubilacion': cfg.aportesTrabajador.jubilacion,
        'cfg-td-obrasocial': cfg.aportesTrabajador.obraSocial,
        'cfg-td-pami': cfg.aportesTrabajador.pami,
        'cfg-td-sindical': cfg.aportesTrabajador.sindical,
        'cfg-td-otros': cfg.aportesTrabajador.otros,
        'cfg-em-jubilacion': cfg.contribucionesEmpleador.jubilacion,
        'cfg-em-obrasocial': cfg.contribucionesEmpleador.obraSocial,
        'cfg-em-pami': cfg.contribucionesEmpleador.pami,
        'cfg-em-art': cfg.contribucionesEmpleador.art,
        'cfg-em-sindical': cfg.contribucionesEmpleador.sindical,
        'cfg-em-camaras': cfg.contribucionesEmpleador.camaras,
        'cfg-em-otros': cfg.contribucionesEmpleador.otros
    };
    Object.keys(valores).forEach(id => {
        const el = document.getElementById(id);
        if (el) el.value = valores[id] ? valores[id] : '';
    });
}

function guardarConfigRecibo() {
    const leer = id => {
        const v = parseFloat(document.getElementById(id).value);
        return isNaN(v) || v < 0 ? 0 : v;
    };
    configRecibo = {
        aportesTrabajador: {
            jubilacion: leer('cfg-td-jubilacion'),
            obraSocial: leer('cfg-td-obrasocial'),
            pami: leer('cfg-td-pami'),
            sindical: leer('cfg-td-sindical'),
            otros: leer('cfg-td-otros')
        },
        contribucionesEmpleador: {
            jubilacion: leer('cfg-em-jubilacion'),
            obraSocial: leer('cfg-em-obrasocial'),
            pami: leer('cfg-em-pami'),
            art: leer('cfg-em-art'),
            sindical: leer('cfg-em-sindical'),
            camaras: leer('cfg-em-camaras'),
            otros: leer('cfg-em-otros')
        }
    };
    saveData();
    alert('Configuración guardada. Los % se aplican al generar la Vista Previa / Impresión del recibo.');
}

function pintarGraficoCostoLaboral(totalHaberes, contribuciones, costoLaboral) {
    const cont = document.getElementById('render-grafico');
    if (!cont) return;

    const base = costoLaboral > 0 ? costoLaboral : 1;
    const segments = [{ clave: 'remuneracion', nombre: 'Remuneración bruta', color: COLORES_COSTO.remuneracion, monto: totalHaberes }];
    contribuciones.forEach(c => segments.push({ clave: c.clave, nombre: c.nombre, color: COLORES_COSTO[c.clave] || COLORES_COSTO.otros, monto: c.monto }));

    let acc = 0;
    const stops = segments.map(s => {
        const inicio = acc;
        acc += (s.monto / base) * 100;
        return s.color + ' ' + inicio.toFixed(2) + '% ' + acc.toFixed(2) + '%';
    });
    const gradiente = 'conic-gradient(' + stops.join(', ') + ')';

    cont.innerHTML = `
        <div style="display:flex; align-items:center; gap:30px; flex-wrap:wrap;">
            <div style="width:150px; height:150px; border-radius:50%; background:${gradiente}; border:1px solid #999; flex-shrink:0;"></div>
            <table style="flex:1; min-width:280px;">
                <thead>
                    <tr>
                        <th style="border:1px solid #ccc; padding:6px; text-align:left;">Composición del costo laboral</th>
                        <th style="border:1px solid #ccc; padding:6px; text-align:right;">%</th>
                        <th style="border:1px solid #ccc; padding:6px; text-align:right;">Importe</th>
                    </tr>
                </thead>
                <tbody>
                    ${segments.map(s => `
                        <tr>
                            <td style="border:1px solid #ccc; padding:6px;">
                                <span style="display:inline-block; width:10px; height:10px; background:${s.color}; margin-right:6px; vertical-align:middle;"></span>${esc(s.nombre)}
                            </td>
                            <td style="border:1px solid #ccc; padding:6px; text-align:right;">${((s.monto / base) * 100).toFixed(1)}%</td>
                            <td style="border:1px solid #ccc; padding:6px; text-align:right;">$${s.monto.toLocaleString('es-AR')}</td>
                        </tr>
                    `).join('')}
                    <tr style="background:#f3f4f6;">
                        <td style="border:1px solid #ccc; padding:6px;"><strong>COSTO TOTAL LABORAL</strong></td>
                        <td style="border:1px solid #ccc; padding:6px; text-align:right;">100%</td>
                        <td style="border:1px solid #ccc; padding:6px; text-align:right;"><strong>$${costoLaboral.toLocaleString('es-AR')}</strong></td>
                    </tr>
                </tbody>
            </table>
        </div>
        <div style="height:26px; display:flex; border:1px solid #999; margin-top:12px;">
            ${segments.map(s => `<div style="width:${((s.monto / base) * 100).toFixed(2)}%; background:${s.color};"></div>`).join('')}
        </div>
        <p style="font-size:0.72rem; color:#555; margin-top:6px; text-align:right;">Gráfico de composición del costo laboral — Anexo III, Dec 407/2026</p>
    `;
}

// --- Generación Recibo ---
function generarRecibo() {
    const empId = document.getElementById('recibo-emp').value;
    const periodo = document.getElementById('recibo-mes').value; // YYYY-MM

    if(!empId || !periodo) { alert("Selecciona Empleado y Período"); return false; }

    const empleado = empleados.find(e => e.id === parseInt(empId));
    if(!empleado) return false;

    // Sección 1: encabezado con datos de la empresa
    document.getElementById('recibo-empresa-nombre').innerText = EMPRESA.nombre;
    document.getElementById('recibo-empresa-cuit').innerText = EMPRESA.cuit;
    document.getElementById('recibo-empresa-domicilio').innerText = EMPRESA.domicilio;
    document.getElementById('recibo-empresa-actividad').innerText = EMPRESA.actividad;
    document.getElementById('render-lugar-pago').innerText = EMPRESA.lugarPago;
    document.getElementById('render-forma-pago').innerText = EMPRESA.modalidadPago;

    document.getElementById('render-nombre').innerText = empleado.nombre;
    document.getElementById('render-cuil').innerText = empleado.cuil || "N/A";
    document.getElementById('render-puesto').innerText = empleado.puesto || empleado.categoriaNombre || "N/A";
    document.getElementById('render-convenio').innerText = empleado.convenioNombre || "Sin convenio cargado";
    document.getElementById('render-categoria').innerText = empleado.categoriaNombre || "Sin categoría cargada";

    const pArr = periodo.split('-');
    const mesNombre = new Date(pArr[0], pArr[1]-1).toLocaleString('es-AR', { month: 'long' });
    document.getElementById('render-periodo').innerText = `Período: ${mesNombre.toUpperCase()} ${pArr[0]}`;

    if (!configRecibo) cargarConfigRecibo();
    const cfg = configRecibo;

    const haberesRows = [];
    const deduccionesRows = [];
    haberesRows.push({ nombre: 'Sueldo Básico', monto: empleado.sueldo });
    let totalHaberes = empleado.sueldo;

    // Novedades de este empleado
    const novEmp = novedades.filter(n => n.empId === empleado.id);
    novEmp.forEach(n => {
        if(n.tipo === 'adelanto' || n.tipo === 'falta') {
            deduccionesRows.push({ nombre: (n.tipo === 'adelanto' ? 'Adelanto de Sueldo' : 'Día de Ausencia') + ' (' + n.fecha + ')', monto: n.monto });
        } else if(n.tipo === 'premio') {
            totalHaberes += n.monto;
            haberesRows.push({ nombre: 'Premio / Bono (' + n.fecha + ')', monto: n.monto });
        }
    });

    // Conceptos configurables aplicados a este empleado y período
    const aplEmp = aplicacionesConceptos.filter(a => a.empId === empleado.id && a.periodo === periodo);
    aplEmp.forEach(a => {
        if(a.tipo === 'haber') {
            totalHaberes += a.monto;
            haberesRows.push({ nombre: a.nombre, monto: a.monto });
        } else {
            deduccionesRows.push({ nombre: a.nombre, monto: a.monto });
        }
    });

    // ÍTEM 4 — aportes del trabajador calculados por % (Sección 3)
    Object.keys(ETIQ_APORTE).forEach(clave => {
        const pct = Number(cfg.aportesTrabajador[clave]) || 0;
        if (pct > 0) {
            const monto = Math.round(totalHaberes * pct) / 100;
            deduccionesRows.push({ nombre: 'Aporte ' + ETIQ_APORTE[clave] + ' (' + pct + '%)', monto });
        }
    });

    // ÍTEM 4 — contribuciones del empleador calculadas por % (Sección 4)
    const contribuciones = [];
    let totalContribuciones = 0;
    Object.keys(ETIQ_CONTRIB).forEach(clave => {
        const pct = Number(cfg.contribucionesEmpleador[clave]) || 0;
        if (pct > 0) {
            const monto = Math.round(totalHaberes * pct) / 100;
            totalContribuciones += monto;
            contribuciones.push({ clave, nombre: ETIQ_CONTRIB[clave], pct, monto });
        }
    });

    const totalDeducciones = deduccionesRows.reduce((s, r) => s + r.monto, 0);
    const neto = totalHaberes - totalDeducciones;
    const costoLaboral = totalHaberes + totalContribuciones;

    // Sección 2 — Remuneración
    document.getElementById('render-haberes').innerHTML = haberesRows.map(r => `
        <tr>
            <td style="border: 1px solid #ccc; padding: 8px;">${esc(r.nombre)}</td>
            <td style="border: 1px solid #ccc; padding: 8px; text-align: right;">$${r.monto.toLocaleString('es-AR')}</td>
        </tr>
    `).join('');
    document.getElementById('render-total-haberes').innerText = totalHaberes.toLocaleString('es-AR');

    // Sección 3 — Deducciones
    document.getElementById('render-deducciones').innerHTML = deduccionesRows.length === 0
        ? '<tr><td colspan="2" style="border: 1px solid #ccc; padding: 8px; color: #666;">Sin deducciones en este período.</td></tr>'
        : deduccionesRows.map(r => `
        <tr>
            <td style="border: 1px solid #ccc; padding: 8px;">${esc(r.nombre)}</td>
            <td style="border: 1px solid #ccc; padding: 8px; text-align: right;">$${r.monto.toLocaleString('es-AR')}</td>
        </tr>
    `).join('');
    document.getElementById('render-total-deducciones').innerText = totalDeducciones.toLocaleString('es-AR');
    document.getElementById('render-neto').innerText = neto.toLocaleString('es-AR');

    // Sección 4 — contribuciones + resumen + gráfico Anexo III
    const tbodyContrib = document.getElementById('render-contribuciones');
    if (contribuciones.length === 0) {
        tbodyContrib.innerHTML = '<tr><td colspan="3" style="border: 1px solid #ccc; padding: 8px; color: #666;">Sin % de contribuciones cargados. Cargalos en "Aportes y Contrib." para que se calculen automáticamente.</td></tr>';
    } else {
        tbodyContrib.innerHTML = contribuciones.map(c => `
            <tr>
                <td style="border: 1px solid #ccc; padding: 8px;">${esc(c.nombre)}</td>
                <td style="border: 1px solid #ccc; padding: 8px; text-align: right;">${c.pct}%</td>
                <td style="border: 1px solid #ccc; padding: 8px; text-align: right;">$${c.monto.toLocaleString('es-AR')}</td>
            </tr>
        `).join('');
    }
    document.getElementById('render-total-contribuciones').innerText = totalContribuciones.toLocaleString('es-AR');
    document.getElementById('render-resumen-haberes').innerText = totalHaberes.toLocaleString('es-AR');
    document.getElementById('render-resumen-deducciones').innerText = totalDeducciones.toLocaleString('es-AR');
    document.getElementById('render-resumen-neto').innerText = neto.toLocaleString('es-AR');
    document.getElementById('render-costo-laboral').innerText = costoLaboral.toLocaleString('es-AR');

    pintarGraficoCostoLaboral(totalHaberes, contribuciones, costoLaboral);

    document.getElementById('vista-recibo-container').style.display = 'block';
    return true;
}

function imprimirRecibo() {
    if(generarRecibo()) window.print();
}

